pub struct Label {
    pub width: u32,
    pub pixels: Vec<u8>,
}
pub fn editor_raster(which: u32) -> Label {
    let (width, shade, runs) = match which {
        0 => (170, 255, editor_label_0()),
        1 => (83, 200, editor_label_1()),
        2 => (688, 180, editor_label_2()),
        3 => (97, 255, editor_label_3()),
        4 => (102, 255, editor_label_4()),
        5 => (92, 255, editor_label_5()),
        6 => (96, 255, editor_label_6()),
        7 => (116, 255, editor_label_7()),
        8 => (112, 255, editor_label_8()),
        9 => (114, 255, editor_label_9()),
        10 => (186, 150, editor_label_10()),
        11 => (186, 150, editor_label_11()),
        12 => (186, 150, editor_label_12()),
        13 => (186, 150, editor_label_13()),
        14 => (186, 150, editor_label_14()),
        15 => (186, 150, editor_label_15()),
        16 => (150, 255, editor_label_16()),
        17 => (415, 180, editor_label_17()),
        _ => (0, 0, &[] as &[u8]),
    };
    let mut pixels = Vec::new();
    pixels.resize(width * 31 * 4, 0u8);
    for pixel in pixels.chunks_mut(4) {
        pixel[0] = shade;
        pixel[1] = shade;
        pixel[2] = shade;
    }
    let mut at = 0;
    for pair in runs.chunks(2) {
        for _ in 0..pair[0] {
            pixels[at * 4 + 3] = pair[1];
            at += 1;
        }
    }
    Label {
        width: width as u32,
        pixels,
    }
}
